namespace BatchRenameStudio.Core;

/// <summary>
/// The one and only place that splits a file name into base + extension.
/// Contract rule 2: <c>dot</c> is the index of the LAST '.'; when <c>dot &gt; 0</c> the base is
/// name[0..dot) and the extension is name[dot+1..] (no leading dot). Otherwise the whole name is
/// the base and the extension is empty — so ".gitignore" has base ".gitignore" and ext "".
/// </summary>
public static class NameParts
{
    public static (string Base, string Ext) Split(string name)
    {
        var dot = name.LastIndexOf('.');
        if (dot > 0)
        {
            return (name[..dot], name[(dot + 1)..]);
        }

        return (name, string.Empty);
    }

    /// <summary>Contract rule 12: base + "." + ext, or just base when ext is empty.</summary>
    public static string Join(string baseName, string ext)
        => ext.Length > 0 ? baseName + "." + ext : baseName;
}

