namespace BatchRenameStudio.Core;

/// <summary>
/// Contract rule 13, first bullet: decides whether a proposed name is "invalid".
/// The checks are intentionally spelled out literally rather than delegated to
/// <see cref="Path.GetInvalidFileNameChars"/>, whose content is platform dependent.
/// </summary>
public static class NameValidator
{
    public const int MaxNameLength = 255;

    private static readonly char[] ForbiddenChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly HashSet<string> ReservedDeviceNames = BuildReservedNames();

    /// <summary>Returns true when <paramref name="name"/> must be reported as "invalid".</summary>
    public static bool IsInvalid(string name, out string reason)
    {
        if (name.Length == 0)
        {
            reason = "empty name";
            return true;
        }

        if (name.Length > MaxNameLength)
        {
            reason = $"name longer than {MaxNameLength} characters";
            return true;
        }

        foreach (var c in name)
        {
            if (c < ' ')
            {
                reason = $"control character U+{(int)c:X4}";
                return true;
            }

            if (Array.IndexOf(ForbiddenChars, c) >= 0)
            {
                reason = $"forbidden character '{c}'";
                return true;
            }
        }

        var (baseName, _) = NameParts.Split(name);
        if (ReservedDeviceNames.Contains(baseName))
        {
            reason = "reserved device name";
            return true;
        }

        reason = string.Empty;
        return false;
    }

    private static HashSet<string> BuildReservedNames()
    {
        var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "CON", "PRN", "AUX", "NUL" };
        for (var i = 1; i <= 9; i++)
        {
            set.Add("COM" + i);
            set.Add("LPT" + i);
        }

        return set;
    }
}

