using System.Globalization;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>
/// The mutable state a step operates on.
/// <para>
/// Under <see cref="ApplyToMode.Name"/> the extension is held apart in <see cref="Ext"/> and the
/// steps see only the base name in <see cref="Text"/>. Under
/// <see cref="ApplyToMode.NameAndExtension"/>, <see cref="Text"/> IS the whole proposed name and
/// <see cref="Ext"/> is unused (contract rules 3 and 12).
/// </para>
/// </summary>
internal sealed class TargetState
{
    public string Text = string.Empty;

    public string Ext = string.Empty;

    public bool SeparateExt;

    public string Compose() => SeparateExt ? NameParts.Join(Text, Ext) : Text;
}

internal interface ICompiledStep
{
    /// <param name="index">0-based position of the file in processing order.</param>
    void Apply(TargetState state, int index);
}

/// <summary>Turns a declarative <see cref="RuleSet"/> into an executable pipeline.</summary>
internal static class StepCompiler
{
    /// <summary>
    /// A generous ceiling: a pathological user regex should degrade into "no change" rather than
    /// hang the GUI or the headless run.
    /// </summary>
    public static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(5);

    public static ICompiledStep[] Compile(RuleSet rules)
    {
        var compiled = new ICompiledStep[rules.Steps.Count];
        for (var i = 0; i < rules.Steps.Count; i++)
        {
            compiled[i] = CompileOne(rules.Steps[i]);
        }

        return compiled;
    }

    private static ICompiledStep CompileOne(RuleStep step) => step switch
    {
        ReplaceStep s => new CompiledReplace(s),
        InsertStep s => new CompiledInsert(s),
        RemoveStep s => new CompiledRemove(s),
        SequenceStep s => new CompiledSequence(s),
        CaseStep s => new CompiledCase(s),
        ExtensionStep s => new CompiledExtension(s),
        _ => throw new ArgumentOutOfRangeException(nameof(step), $"unsupported step type {step.GetType().Name}"),
    };

    private sealed class CompiledReplace : ICompiledStep
    {
        private readonly string _find;
        private readonly string _replaceWith;
        private readonly StringComparison _comparison;
        private readonly Regex? _regex;

        public CompiledReplace(ReplaceStep s)
        {
            _find = s.Find;
            _replaceWith = s.ReplaceWith;
            _comparison = s.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;

            if (s.Regex)
            {
                var options = RegexOptions.CultureInvariant;
                if (s.IgnoreCase)
                {
                    options |= RegexOptions.IgnoreCase;
                }

                // Throws for a malformed pattern; callers surface that as a rule-set error.
                _regex = new Regex(s.Find, options, RegexTimeout);
            }
        }

        public void Apply(TargetState state, int index)
        {
            if (_regex is not null)
            {
                try
                {
                    state.Text = _regex.Replace(state.Text, _replaceWith);
                }
                catch (RegexMatchTimeoutException)
                {
                    // Leave the name untouched rather than producing a half-applied result.
                }

                return;
            }

            if (_find.Length == 0)
            {
                return;
            }

            state.Text = state.Text.Replace(_find, _replaceWith, _comparison);
        }
    }

    private sealed class CompiledInsert : ICompiledStep
    {
        private readonly string _text;
        private readonly InsertPosition _position;
        private readonly int _index;

        public CompiledInsert(InsertStep s)
        {
            _text = s.Text;
            _position = s.Position;
            _index = s.Index;
        }

        public void Apply(TargetState state, int index)
        {
            switch (_position)
            {
                case InsertPosition.Prefix:
                    state.Text = _text + state.Text;
                    break;
                case InsertPosition.Suffix:
                    state.Text += _text;
                    break;
                default:
                    var at = Math.Clamp(_index, 0, state.Text.Length);
                    state.Text = state.Text.Insert(at, _text);
                    break;
            }
        }
    }

    private sealed class CompiledRemove : ICompiledStep
    {
        private readonly int _from;
        private readonly int _count;

        public CompiledRemove(RemoveStep s)
        {
            _from = s.From;
            _count = s.Count;
        }

        public void Apply(TargetState state, int index)
        {
            var length = state.Text.Length;
            var from = Math.Clamp(_from, 0, length);
            var count = Math.Clamp(_count, 0, length - from);
            if (count == 0)
            {
                return;
            }

            state.Text = state.Text.Remove(from, count);
        }
    }

    private sealed class CompiledSequence : ICompiledStep
    {
        private static readonly Regex TokenPattern =
            new(@"\{n:(0+)\}", RegexOptions.CultureInvariant | RegexOptions.Compiled);

        private readonly string _pattern;
        private readonly long _start;
        private readonly long _step;
        private readonly SequencePosition _position;

        public CompiledSequence(SequenceStep s)
        {
            _pattern = s.Pattern;
            _start = s.Start;
            _step = s.Step;
            _position = s.Position;
        }

        public void Apply(TargetState state, int index)
        {
            // Contract rule 9: the counter advances for EVERY file in processing order,
            // whatever that file's final status turns out to be.
            var value = _start + ((long)index * _step);
            var rendered = TokenPattern.Replace(
                _pattern,
                m => value.ToString(new string('0', m.Groups[1].Value.Length), CultureInfo.InvariantCulture));

            state.Text = _position == SequencePosition.Prefix
                ? rendered + state.Text
                : state.Text + rendered;
        }
    }

    private sealed class CompiledCase : ICompiledStep
    {
        private readonly CaseMode _mode;

        public CompiledCase(CaseStep s) => _mode = s.Mode;

        public void Apply(TargetState state, int index)
            => state.Text = CaseTransform.Apply(state.Text, _mode);
    }

    private sealed class CompiledExtension : ICompiledStep
    {
        private readonly ExtensionMode _mode;
        private readonly string _value;

        public CompiledExtension(ExtensionStep s)
        {
            _mode = s.Mode;
            _value = s.Value;
        }

        public void Apply(TargetState state, int index)
        {
            // Contract rule 11: always operates on the extension, regardless of applyTo.
            if (state.SeparateExt)
            {
                state.Ext = Transform(state.Ext);
                return;
            }

            // applyTo = nameAndExtension: act on the trailing extension of the current string.
            var (baseName, ext) = NameParts.Split(state.Text);
            state.Text = NameParts.Join(baseName, Transform(ext));
        }

        private string Transform(string ext) => _mode switch
        {
            ExtensionMode.Lower => ext.ToLowerInvariant(),
            ExtensionMode.Upper => ext.ToUpperInvariant(),
            _ => _value,
        };
    }
}

/// <summary>Contract rule 10.</summary>
public static class CaseTransform
{
    public static string Apply(string text, CaseMode mode) => mode switch
    {
        CaseMode.Upper => text.ToUpperInvariant(),
        CaseMode.Lower => text.ToLowerInvariant(),
        _ => ToTitle(text),
    };

    /// <summary>
    /// For each maximal run of Unicode letters: uppercase the first character, lowercase the rest.
    /// Every non-letter is left exactly as it was, and also breaks the run.
    /// </summary>
    public static string ToTitle(string text)
    {
        var chars = text.ToCharArray();
        var atRunStart = true;
        for (var i = 0; i < chars.Length; i++)
        {
            if (char.IsLetter(chars[i]))
            {
                chars[i] = atRunStart ? char.ToUpperInvariant(chars[i]) : char.ToLowerInvariant(chars[i]);
                atRunStart = false;
            }
            else
            {
                atRunStart = true;
            }
        }

        return new string(chars);
    }
}

