namespace BatchRenameStudio.Core;

/// <summary>
/// Pure, filesystem-free core: given the files of a folder and a rule set, produce the plan.
/// Both the headless <c>--plan</c> mode and the GUI preview go through here, so what the GUI
/// shows and what the contract emits can never drift apart.
/// </summary>
public static class PlanBuilder
{
    public static RenamePlan Build(IEnumerable<FileEntry> files, RuleSet rules)
    {
        var ordered = SortForProcessing(files, rules.Sort);
        var steps = StepCompiler.Compile(rules);

        var proposed = new string[ordered.Count];
        for (var i = 0; i < ordered.Count; i++)
        {
            proposed[i] = Propose(ordered[i].Name, rules.ApplyTo, steps, i);
        }

        var existingCounts = CountNames(ordered.Select(f => f.Name));
        var proposedCounts = CountNames(proposed);

        var items = new List<PlanItem>(ordered.Count);
        int ok = 0, collision = 0, unchanged = 0, invalid = 0;

        for (var i = 0; i < ordered.Count; i++)
        {
            var original = ordered[i].Name;
            var candidate = proposed[i];
            var status = Classify(original, candidate, existingCounts, proposedCounts, out var reason);

            switch (status)
            {
                case PlanStatus.Ok: ok++; break;
                case PlanStatus.Collision: collision++; break;
                case PlanStatus.Unchanged: unchanged++; break;
                default: invalid++; break;
            }

            items.Add(new PlanItem
            {
                Original = original,
                Proposed = candidate,
                Status = status,
                Reason = reason,
            });
        }

        return new RenamePlan
        {
            Items = items,
            Summary = new PlanSummary
            {
                Total = items.Count,
                Ok = ok,
                Collision = collision,
                Unchanged = unchanged,
                Invalid = invalid,
            },
        };
    }

    /// <summary>
    /// Contract rule 5. "name" is ordinal (codepoint) ascending and case-sensitive; the timestamp
    /// modes fall back to the same ordinal comparison so that ties stay deterministic (rule 15).
    /// </summary>
    public static List<FileEntry> SortForProcessing(IEnumerable<FileEntry> files, SortMode sort) => sort switch
    {
        SortMode.Created => files
            .OrderBy(f => f.CreatedUtc)
            .ThenBy(f => f.Name, StringComparer.Ordinal)
            .ToList(),
        SortMode.Modified => files
            .OrderBy(f => f.ModifiedUtc)
            .ThenBy(f => f.Name, StringComparer.Ordinal)
            .ToList(),
        _ => files
            .OrderBy(f => f.Name, StringComparer.Ordinal)
            .ToList(),
    };

    /// <summary>Runs the whole pipeline over one file name and returns the proposed name.</summary>
    public static string Propose(string originalName, ApplyToMode applyTo, ICompiledStepList steps, int index)
        => Propose(originalName, applyTo, steps.Steps, index);

    internal static string Propose(string originalName, ApplyToMode applyTo, ICompiledStep[] steps, int index)
    {
        var state = new TargetState();
        if (applyTo == ApplyToMode.Name)
        {
            var (baseName, ext) = NameParts.Split(originalName);
            state.Text = baseName;
            state.Ext = ext;
            state.SeparateExt = true;
        }
        else
        {
            state.Text = originalName;
            state.SeparateExt = false;
        }

        foreach (var step in steps)
        {
            step.Apply(state, index);
        }

        return state.Compose();
    }

    /// <summary>Contract rule 13 — first match wins.</summary>
    private static string Classify(
        string original,
        string proposed,
        Dictionary<string, int> existingCounts,
        Dictionary<string, int> proposedCounts,
        out string reason)
    {
        if (NameValidator.IsInvalid(proposed, out var invalidReason))
        {
            reason = invalidReason;
            return PlanStatus.Invalid;
        }

        existingCounts.TryGetValue(proposed, out var existing);
        var selfContribution = string.Equals(proposed, original, StringComparison.OrdinalIgnoreCase) ? 1 : 0;
        if (existing - selfContribution > 0)
        {
            reason = "another file in the folder already uses this name";
            return PlanStatus.Collision;
        }

        proposedCounts.TryGetValue(proposed, out var duplicates);
        if (duplicates > 1)
        {
            reason = "another item proposes the same name";
            return PlanStatus.Collision;
        }

        if (string.Equals(proposed, original, StringComparison.Ordinal))
        {
            reason = string.Empty;
            return PlanStatus.Unchanged;
        }

        reason = string.Empty;
        return PlanStatus.Ok;
    }

    private static Dictionary<string, int> CountNames(IEnumerable<string> names)
    {
        var counts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var name in names)
        {
            counts.TryGetValue(name, out var n);
            counts[name] = n + 1;
        }

        return counts;
    }
}

/// <summary>
/// Opaque handle to a compiled pipeline, so the GUI can compile once and reuse across previews
/// without the internal step types leaking into the public surface.
/// </summary>
public sealed class ICompiledStepList
{
    internal ICompiledStep[] Steps { get; }

    internal ICompiledStepList(ICompiledStep[] steps) => Steps = steps;

    public static ICompiledStepList Compile(RuleSet rules) => new(StepCompiler.Compile(rules));
}

