using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Raised for anything wrong with a <c>rules.json</c>; carries a user-facing message.</summary>
public sealed class RuleSetFormatException : Exception
{
    public RuleSetFormatException(string message, Exception? inner = null)
        : base(message, inner)
    {
    }
}

/// <summary>
/// Reader/writer for the fixed <c>rules.json</c> schema. Parsing is hand-rolled rather than
/// attribute-driven so the polymorphic <c>op</c> discriminator and the per-op defaults stay
/// explicit and easy to check against the contract.
/// </summary>
public static class RuleSetJson
{
    private static readonly JsonDocumentOptions ReaderOptions = new()
    {
        AllowTrailingCommas = true,
        CommentHandling = JsonCommentHandling.Skip,
    };

    public static RuleSet Load(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path);
        }
        catch (Exception ex)
        {
            throw new RuleSetFormatException($"cannot read rules file '{path}': {ex.Message}", ex);
        }

        return Parse(text);
    }

    public static RuleSet Parse(string json)
    {
        JsonDocument doc;
        try
        {
            doc = JsonDocument.Parse(json, ReaderOptions);
        }
        catch (JsonException ex)
        {
            throw new RuleSetFormatException($"rules file is not valid JSON: {ex.Message}", ex);
        }

        using (doc)
        {
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
            {
                throw new RuleSetFormatException("rules file must contain a JSON object at the top level");
            }

            var rules = new RuleSet
            {
                ApplyTo = ReadEnum(root, "applyTo", ApplyToMode.Name, new Dictionary<string, ApplyToMode>(StringComparer.OrdinalIgnoreCase)
                {
                    ["name"] = ApplyToMode.Name,
                    ["nameAndExtension"] = ApplyToMode.NameAndExtension,
                }),
                Sort = ReadEnum(root, "sort", SortMode.Name, new Dictionary<string, SortMode>(StringComparer.OrdinalIgnoreCase)
                {
                    ["name"] = SortMode.Name,
                    ["created"] = SortMode.Created,
                    ["modified"] = SortMode.Modified,
                }),
            };

            if (TryGet(root, "steps", out var steps))
            {
                if (steps.ValueKind != JsonValueKind.Array)
                {
                    throw new RuleSetFormatException("\"steps\" must be an array");
                }

                var index = 0;
                foreach (var element in steps.EnumerateArray())
                {
                    rules.Steps.Add(ParseStep(element, index));
                    index++;
                }
            }

            return rules;
        }
    }

    private static RuleStep ParseStep(JsonElement element, int index)
    {
        if (element.ValueKind != JsonValueKind.Object)
        {
            throw new RuleSetFormatException($"steps[{index}] must be an object");
        }

        var op = ReadString(element, "op", null)
                 ?? throw new RuleSetFormatException($"steps[{index}] is missing \"op\"");

        switch (op.ToLowerInvariant())
        {
            case "replace":
                return new ReplaceStep
                {
                    Find = ReadString(element, "find", string.Empty)!,
                    ReplaceWith = ReadString(element, "replaceWith", string.Empty)!,
                    Regex = ReadBool(element, "regex", false),
                    IgnoreCase = ReadBool(element, "ignoreCase", false),
                };

            case "insert":
                return new InsertStep
                {
                    Text = ReadString(element, "text", string.Empty)!,
                    Position = ReadEnum(element, "position", InsertPosition.Prefix, new Dictionary<string, InsertPosition>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["prefix"] = InsertPosition.Prefix,
                        ["suffix"] = InsertPosition.Suffix,
                        ["index"] = InsertPosition.Index,
                    }),
                    Index = ReadInt(element, "index", 0),
                };

            case "remove":
                return new RemoveStep
                {
                    From = ReadInt(element, "from", 0),
                    Count = ReadInt(element, "count", 0),
                };

            case "sequence":
                return new SequenceStep
                {
                    Pattern = ReadString(element, "pattern", "{n:000}")!,
                    Start = ReadInt(element, "start", 1),
                    Step = ReadInt(element, "step", 1),
                    Position = ReadEnum(element, "position", SequencePosition.Prefix, new Dictionary<string, SequencePosition>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["prefix"] = SequencePosition.Prefix,
                        ["suffix"] = SequencePosition.Suffix,
                    }),
                };

            case "case":
                return new CaseStep
                {
                    Mode = ReadEnum(element, "mode", CaseMode.Lower, new Dictionary<string, CaseMode>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["upper"] = CaseMode.Upper,
                        ["lower"] = CaseMode.Lower,
                        ["title"] = CaseMode.Title,
                    }),
                };

            case "extension":
                return new ExtensionStep
                {
                    Mode = ReadEnum(element, "mode", ExtensionMode.Lower, new Dictionary<string, ExtensionMode>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["lower"] = ExtensionMode.Lower,
                        ["upper"] = ExtensionMode.Upper,
                        ["set"] = ExtensionMode.Set,
                    }),
                    Value = ReadString(element, "value", string.Empty)!,
                };

            default:
                throw new RuleSetFormatException($"steps[{index}] has unknown op \"{op}\"");
        }
    }

    /// <summary>Serialises back into the exact contract schema (used by the GUI's "Save rules").</summary>
    public static string Serialize(RuleSet rules)
    {
        var buffer = new MemoryStream();
        using (var writer = new Utf8JsonWriter(buffer, new JsonWriterOptions
        {
            Indented = true,
            Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
        }))
        {
            writer.WriteStartObject();
            writer.WriteString("applyTo", rules.ApplyTo == ApplyToMode.Name ? "name" : "nameAndExtension");
            writer.WriteString("sort", rules.Sort.ToString().ToLowerInvariant());
            writer.WriteStartArray("steps");

            foreach (var step in rules.Steps)
            {
                writer.WriteStartObject();
                writer.WriteString("op", step.Op);
                switch (step)
                {
                    case ReplaceStep s:
                        writer.WriteString("find", s.Find);
                        writer.WriteString("replaceWith", s.ReplaceWith);
                        writer.WriteBoolean("regex", s.Regex);
                        writer.WriteBoolean("ignoreCase", s.IgnoreCase);
                        break;
                    case InsertStep s:
                        writer.WriteString("text", s.Text);
                        writer.WriteString("position", s.Position.ToString().ToLowerInvariant());
                        writer.WriteNumber("index", s.Index);
                        break;
                    case RemoveStep s:
                        writer.WriteNumber("from", s.From);
                        writer.WriteNumber("count", s.Count);
                        break;
                    case SequenceStep s:
                        writer.WriteString("pattern", s.Pattern);
                        writer.WriteNumber("start", s.Start);
                        writer.WriteNumber("step", s.Step);
                        writer.WriteString("position", s.Position.ToString().ToLowerInvariant());
                        break;
                    case CaseStep s:
                        writer.WriteString("mode", s.Mode.ToString().ToLowerInvariant());
                        break;
                    case ExtensionStep s:
                        writer.WriteString("mode", s.Mode.ToString().ToLowerInvariant());
                        writer.WriteString("value", s.Value);
                        break;
                }

                writer.WriteEndObject();
            }

            writer.WriteEndArray();
            writer.WriteEndObject();
        }

        return Encoding.UTF8.GetString(buffer.ToArray());
    }

    public static void Save(string path, RuleSet rules)
        => Utf8NoBom.WriteAllText(path, RuleSetJson.Serialize(rules));

    private static bool TryGet(JsonElement obj, string name, out JsonElement value)
    {
        if (obj.TryGetProperty(name, out value))
        {
            return true;
        }

        // Be forgiving about casing of the schema keys themselves.
        foreach (var property in obj.EnumerateObject())
        {
            if (string.Equals(property.Name, name, StringComparison.OrdinalIgnoreCase))
            {
                value = property.Value;
                return true;
            }
        }

        value = default;
        return false;
    }

    private static string? ReadString(JsonElement obj, string name, string? fallback)
    {
        if (!TryGet(obj, name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return fallback;
        }

        if (value.ValueKind != JsonValueKind.String)
        {
            throw new RuleSetFormatException($"\"{name}\" must be a string");
        }

        return value.GetString() ?? fallback;
    }

    private static bool ReadBool(JsonElement obj, string name, bool fallback)
    {
        if (!TryGet(obj, name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return fallback;
        }

        return value.ValueKind switch
        {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            _ => throw new RuleSetFormatException($"\"{name}\" must be true or false"),
        };
    }

    private static int ReadInt(JsonElement obj, string name, int fallback)
    {
        if (!TryGet(obj, name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return fallback;
        }

        if (value.ValueKind != JsonValueKind.Number || !value.TryGetInt32(out var parsed))
        {
            throw new RuleSetFormatException($"\"{name}\" must be a 32-bit integer");
        }

        return parsed;
    }

    private static TEnum ReadEnum<TEnum>(
        JsonElement obj,
        string name,
        TEnum fallback,
        IReadOnlyDictionary<string, TEnum> map)
        where TEnum : struct, Enum
    {
        if (!TryGet(obj, name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return fallback;
        }

        if (value.ValueKind != JsonValueKind.String)
        {
            throw new RuleSetFormatException($"\"{name}\" must be a string");
        }

        var text = value.GetString() ?? string.Empty;
        if (!map.TryGetValue(text, out var parsed))
        {
            throw new RuleSetFormatException(
                $"\"{name}\" has unsupported value \"{text}\" (expected one of: {string.Join(", ", map.Keys)})");
        }

        return parsed;
    }
}

