using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>
/// Every file this tool writes goes through here: UTF-8, never a BOM, always LF line endings,
/// so output is byte-identical across machines and shells (contract rule 15).
/// </summary>
public static class Utf8NoBom
{
    private static readonly UTF8Encoding Encoding = new(encoderShouldEmitUTF8Identifier: false);

    public static void WriteAllText(string path, string text)
        => WriteAllBytes(path, Encoding.GetBytes(NormalizeNewlines(text)));

    public static void WriteAllBytes(string path, byte[] bytes)
    {
        var directory = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(directory))
        {
            Directory.CreateDirectory(directory);
        }

        File.WriteAllBytes(path, bytes);
    }

    /// <summary>
    /// CRLF/CR to LF. Safe on JSON: a literal CR inside a string value is always escaped as
    /// <c>\r</c> by the writer, so only the indentation can carry raw carriage returns.
    /// </summary>
    public static string NormalizeNewlines(string text)
        => text.Replace("\r\n", "\n").Replace("\r", "\n");
}

