namespace BatchRenameStudio.Core;

/// <summary>Contract rule 1: regular files directly inside the folder, non-recursive, no directories.</summary>
public static class FolderScanner
{
    public static List<FileEntry> Scan(string folder)
    {
        var info = new DirectoryInfo(folder);
        if (!info.Exists)
        {
            throw new DirectoryNotFoundException($"folder not found: {folder}");
        }

        var entries = new List<FileEntry>();
        foreach (var file in info.EnumerateFiles("*", SearchOption.TopDirectoryOnly))
        {
            entries.Add(new FileEntry
            {
                Name = file.Name,
                CreatedUtc = file.CreationTimeUtc,
                ModifiedUtc = file.LastWriteTimeUtc,
            });
        }

        return entries;
    }
}

