namespace BatchRenameStudio.Core;

public sealed record RenameOperation(string From, string To);

public sealed record RenameFailure(string From, string To, string Error);

public sealed class RenameOutcome
{
    public required IReadOnlyList<RenameOperation> Applied { get; init; }

    public required IReadOnlyList<RenameFailure> Failures { get; init; }

    public int SucceededCount => Applied.Count;

    public int FailedCount => Failures.Count;
}

/// <summary>
/// Performs the renames of a plan. Only <c>ok</c> items are touched — by the contract's own
/// definitions an <c>ok</c> target can neither exist on disk nor be claimed by another item, so a
/// straight one-pass rename is safe; the only special case is a rename that changes case alone.
/// </summary>
public static class RenameExecutor
{
    public static RenameOutcome Apply(string folder, RenamePlan plan)
        => Apply(folder, plan.Items.Where(i => i.Status == PlanStatus.Ok)
            .Select(i => new RenameOperation(i.Original, i.Proposed)));

    public static RenameOutcome Apply(string folder, IEnumerable<RenameOperation> operations)
    {
        var applied = new List<RenameOperation>();
        var failures = new List<RenameFailure>();

        foreach (var op in operations)
        {
            try
            {
                Move(folder, op.From, op.To);
                applied.Add(op);
            }
            catch (Exception ex)
            {
                failures.Add(new RenameFailure(op.From, op.To, ex.Message));
            }
        }

        return new RenameOutcome { Applied = applied, Failures = failures };
    }

    /// <summary>Reverses a batch, newest operation first, so chains unwind cleanly.</summary>
    public static RenameOutcome Revert(string folder, IReadOnlyList<RenameOperation> operations)
    {
        var reversed = new List<RenameOperation>(operations.Count);
        for (var i = operations.Count - 1; i >= 0; i--)
        {
            reversed.Add(new RenameOperation(operations[i].To, operations[i].From));
        }

        return Apply(folder, reversed);
    }

    private static void Move(string folder, string from, string to)
    {
        var source = Path.Combine(folder, from);
        var destination = Path.Combine(folder, to);

        if (!File.Exists(source))
        {
            throw new FileNotFoundException($"'{from}' is no longer there");
        }

        var caseOnlyChange = string.Equals(from, to, StringComparison.OrdinalIgnoreCase)
                             && !string.Equals(from, to, StringComparison.Ordinal);

        if (caseOnlyChange)
        {
            // NTFS is case-insensitive: bounce through a unique temporary name so the rename is
            // not mistaken for a no-op or an overwrite.
            var temporary = Path.Combine(folder, from + ".brs-tmp-" + Guid.NewGuid().ToString("N")[..8]);
            File.Move(source, temporary);
            try
            {
                File.Move(temporary, destination);
            }
            catch
            {
                File.Move(temporary, source);
                throw;
            }

            return;
        }

        if (File.Exists(destination) || Directory.Exists(destination))
        {
            throw new IOException($"'{to}' already exists");
        }

        File.Move(source, destination);
    }
}

