using System.Globalization;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>One applied batch of renames, the unit of undo.</summary>
public sealed class RenameBatch
{
    public required string Id { get; init; }

    public required DateTime TimestampUtc { get; init; }

    public required string Folder { get; init; }

    public required IReadOnlyList<RenameOperation> Operations { get; init; }

    public string Describe()
        => $"{TimestampUtc.ToLocalTime():yyyy-MM-dd HH:mm:ss} · {Operations.Count} file(s) · {Folder}";
}

/// <summary>
/// Undo model: every apply is journalled to disk before it is offered for undo, so the history
/// survives a crash or a restart, and a batch is undone as a whole (never half of one).
/// </summary>
public sealed class UndoManager
{
    private const int JournalSchemaVersion = 1;
    private const int MaxLoadedBatches = 50;

    private readonly string _historyFolder;
    private readonly List<RenameBatch> _batches = new();
    private readonly Dictionary<string, string> _journalPaths = new(StringComparer.Ordinal);

    public UndoManager()
        : this(DefaultHistoryFolder())
    {
    }

    public UndoManager(string historyFolder)
    {
        _historyFolder = historyFolder;
        LoadHistory();
    }

    public static string DefaultHistoryFolder() => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "BatchRenameStudio",
        "history");

    public bool CanUndo => _batches.Count > 0;

    public RenameBatch? Newest => _batches.Count > 0 ? _batches[^1] : null;

    public IReadOnlyList<RenameBatch> Batches => _batches;

    /// <summary>Records an applied batch and journals it. No-op for an empty operation list.</summary>
    public RenameBatch? Record(string folder, IReadOnlyList<RenameOperation> operations, DateTime timestampUtc)
    {
        if (operations.Count == 0)
        {
            return null;
        }

        var batch = new RenameBatch
        {
            Id = Guid.NewGuid().ToString("N"),
            TimestampUtc = timestampUtc,
            Folder = folder,
            Operations = operations.ToList(),
        };

        _batches.Add(batch);
        TryWriteJournal(batch);
        return batch;
    }

    /// <summary>Reverts the newest batch and removes it from the history.</summary>
    public (RenameBatch Batch, RenameOutcome Outcome)? UndoNewest()
    {
        if (_batches.Count == 0)
        {
            return null;
        }

        var batch = _batches[^1];
        var outcome = RenameExecutor.Revert(batch.Folder, batch.Operations);

        _batches.RemoveAt(_batches.Count - 1);
        RetireJournal(batch.Id);
        return (batch, outcome);
    }

    private void LoadHistory()
    {
        try
        {
            if (!Directory.Exists(_historyFolder))
            {
                return;
            }

            var files = Directory.GetFiles(_historyFolder, "*.json");
            Array.Sort(files, StringComparer.Ordinal);

            foreach (var file in files.TakeLast(MaxLoadedBatches))
            {
                var batch = TryReadJournal(file);
                if (batch is null)
                {
                    continue;
                }

                _batches.Add(batch);
                _journalPaths[batch.Id] = file;
            }
        }
        catch
        {
            // A damaged history must never stop the app from starting.
        }
    }

    private static RenameBatch? TryReadJournal(string path)
    {
        try
        {
            using var document = JsonDocument.Parse(File.ReadAllText(path));
            var root = document.RootElement;
            var operations = new List<RenameOperation>();
            foreach (var element in root.GetProperty("operations").EnumerateArray())
            {
                operations.Add(new RenameOperation(
                    element.GetProperty("from").GetString() ?? string.Empty,
                    element.GetProperty("to").GetString() ?? string.Empty));
            }

            if (operations.Count == 0)
            {
                return null;
            }

            return new RenameBatch
            {
                Id = root.GetProperty("id").GetString() ?? Guid.NewGuid().ToString("N"),
                TimestampUtc = DateTime.Parse(
                    root.GetProperty("timestampUtc").GetString() ?? "1970-01-01T00:00:00Z",
                    CultureInfo.InvariantCulture,
                    DateTimeStyles.AdjustToUniversal | DateTimeStyles.AssumeUniversal),
                Folder = root.GetProperty("folder").GetString() ?? string.Empty,
                Operations = operations,
            };
        }
        catch
        {
            return null;
        }
    }

    private void TryWriteJournal(RenameBatch batch)
    {
        try
        {
            Directory.CreateDirectory(_historyFolder);
            var fileName = string.Create(
                CultureInfo.InvariantCulture,
                $"{batch.TimestampUtc:yyyyMMdd-HHmmss-fff}-{batch.Id[..8]}.json");
            var path = Path.Combine(_historyFolder, fileName);

            var buffer = new MemoryStream();
            using (var writer = new Utf8JsonWriter(buffer, new JsonWriterOptions
            {
                Indented = true,
                Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
            }))
            {
                writer.WriteStartObject();
                writer.WriteNumber("schemaVersion", JournalSchemaVersion);
                writer.WriteString("id", batch.Id);
                writer.WriteString(
                    "timestampUtc",
                    batch.TimestampUtc.ToString("yyyy-MM-ddTHH:mm:ss.fffZ", CultureInfo.InvariantCulture));
                writer.WriteString("folder", batch.Folder);
                writer.WriteStartArray("operations");
                foreach (var op in batch.Operations)
                {
                    writer.WriteStartObject();
                    writer.WriteString("from", op.From);
                    writer.WriteString("to", op.To);
                    writer.WriteEndObject();
                }

                writer.WriteEndArray();
                writer.WriteEndObject();
            }

            Utf8NoBom.WriteAllBytes(path, buffer.ToArray());
            _journalPaths[batch.Id] = path;
        }
        catch
        {
            // Journalling is best effort; in-memory undo still works without it.
        }
    }

    private void RetireJournal(string id)
    {
        if (!_journalPaths.TryGetValue(id, out var path))
        {
            return;
        }

        _journalPaths.Remove(id);
        try
        {
            if (File.Exists(path))
            {
                File.Move(path, path + ".undone", overwrite: true);
            }
        }
        catch
        {
            // Ignored: the batch is already undone in memory.
        }
    }
}

