using System.Runtime.InteropServices;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The app is a <c>WinExe</c>, so it owns no console. When its output is redirected (a pipe or a
/// file) the inherited handles are already valid and must be left untouched; only when there is no
/// handle at all do we attach to the parent console so a human running the CLI sees the summary.
/// </summary>
internal static class ConsoleBridge
{
    private const int StdOutputHandle = -11;
    private const int StdErrorHandle = -12;
    private const uint AttachParentProcess = 0xFFFFFFFF;
    private const uint GenericWrite = 0x40000000;
    private const uint FileShareWrite = 0x00000002;
    private const uint OpenExisting = 3;

    private static readonly IntPtr InvalidHandle = new(-1);

    public static void EnsureAttached()
    {
        try
        {
            if (HasHandle(StdOutputHandle))
            {
                return;
            }

            if (!AttachConsole(AttachParentProcess))
            {
                return;
            }

            RedirectToConsoleDevice(StdOutputHandle, isError: false);
            RedirectToConsoleDevice(StdErrorHandle, isError: true);
        }
        catch
        {
            // Without a console the summary simply goes nowhere; that must never be fatal.
        }
    }

    private static bool HasHandle(int which)
    {
        var handle = GetStdHandle(which);
        return handle != IntPtr.Zero && handle != InvalidHandle;
    }

    private static void RedirectToConsoleDevice(int which, bool isError)
    {
        if (!HasHandle(which))
        {
            var device = CreateFileW(
                "CONOUT$", GenericWrite, FileShareWrite, IntPtr.Zero, OpenExisting, 0, IntPtr.Zero);
            if (device == InvalidHandle)
            {
                return;
            }

            SetStdHandle(which, device);
        }

        var stream = isError ? Console.OpenStandardError() : Console.OpenStandardOutput();
        if (stream == Stream.Null)
        {
            return;
        }

        var writer = new StreamWriter(stream) { AutoFlush = true };
        if (isError)
        {
            Console.SetError(writer);
        }
        else
        {
            Console.SetOut(writer);
        }
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool SetStdHandle(int nStdHandle, IntPtr handle);

    [DllImport("kernel32.dll", SetLastError = true)]
