using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Headless entry point.
/// <code>
/// BatchRenameStudio.exe --plan --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;
/// </code>
/// Exit codes: 0 success · 1 runtime failure (missing folder, I/O) · 2 usage or rules error.
/// In <c>--plan</c> mode stdout carries exactly one summary line; everything else goes to stderr.
/// </summary>
internal static class CommandLine
{
    public const int ExitSuccess = 0;
    public const int ExitRuntimeError = 1;
    public const int ExitUsageError = 2;

    private const string Usage = """
        Batch Rename Studio

          BatchRenameStudio.exe
              Launch the graphical interface.

          BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>
              Compute the rename plan for <folder> and write it to <plan.json>.
              Nothing is renamed. Prints one summary line. Exit code 0 on success.

          BatchRenameStudio.exe --help
              Show this text.
        """;

    public static int Run(string[] args)
    {
        if (args.Any(a => a is "--help" or "-h" or "/?"))
        {
            Console.Out.WriteLine(Usage);
            return ExitSuccess;
        }

        string? dir = null, rules = null, output = null;
        var plan = false;

        for (var i = 0; i < args.Length; i++)
        {
            var arg = args[i];
            switch (arg)
            {
                case "--plan":
                    plan = true;
                    break;
                case "--dir":
                    if (!TryTakeValue(args, ref i, arg, out dir))
                    {
                        return ExitUsageError;
                    }

                    break;
                case "--rules":
                    if (!TryTakeValue(args, ref i, arg, out rules))
                    {
                        return ExitUsageError;
                    }

                    break;
                case "--out":
                    if (!TryTakeValue(args, ref i, arg, out output))
                    {
                        return ExitUsageError;
                    }

                    break;
                default:
                    return Fail(ExitUsageError, $"unknown argument '{arg}'", withUsage: true);
            }
        }

        if (!plan)
        {
            return Fail(ExitUsageError, "--plan is required when arguments are given", withUsage: true);
        }

        if (dir is null || rules is null || output is null)
        {
            return Fail(ExitUsageError, "--plan requires --dir, --rules and --out", withUsage: true);
        }

        return RunPlan(dir, rules, output);
    }

    private static int RunPlan(string dir, string rulesPath, string outputPath)
    {
        RuleSet rules;
        try
        {
            rules = RuleSetJson.Load(rulesPath);
        }
        catch (RuleSetFormatException ex)
        {
            return Fail(ExitUsageError, ex.Message);
        }

        List<FileEntry> files;
        try
        {
            files = FolderScanner.Scan(dir);
        }
        catch (Exception ex)
        {
            return Fail(ExitRuntimeError, ex.Message);
        }

        RenamePlan plan;
        try
        {
            plan = PlanBuilder.Build(files, rules);
        }
        catch (ArgumentException ex)
        {
            // A malformed regex in the rule set surfaces here.
            return Fail(ExitUsageError, $"cannot apply rules: {ex.Message}");
        }

        try
        {
            PlanJson.Save(outputPath, plan);
        }
        catch (Exception ex)
        {
            return Fail(ExitRuntimeError, $"cannot write '{outputPath}': {ex.Message}");
        }

        var s = plan.Summary;
        Console.Out.WriteLine(string.Create(
            CultureInfo.InvariantCulture,
            $"plan written: total={s.Total} ok={s.Ok} collision={s.Collision} unchanged={s.Unchanged} invalid={s.Invalid}"));
        Console.Out.Flush();
        return ExitSuccess;
    }

    private static bool TryTakeValue(string[] args, ref int i, string name, out string? value)
    {
        if (i + 1 >= args.Length)
        {
            Fail(ExitUsageError, $"{name} requires a value", withUsage: true);
            value = null;
            return false;
        }

        value = args[++i];
        return true;
    }

    private static int Fail(int code, string message, bool withUsage = false)
    {
        Console.Error.WriteLine("error: " + message);
        if (withUsage)
        {
            Console.Error.WriteLine();
            Console.Error.WriteLine(Usage);
        }

        Console.Error.Flush();
        return code;
    }
}

