        AutoScaleMode = AutoScaleMode.Dpi;
        Padding = new Padding(12);
        AutoSize = true;
        AutoSizeMode = AutoSizeMode.GrowAndShrink;

        _fields = new TableLayoutPanel
        {
            ColumnCount = 2,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            Dock = DockStyle.Top,
        };
        _fields.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        _fields.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 320));

        BuildFields();

        var ok = new Button { Text = "OK", DialogResult = DialogResult.OK, AutoSize = true, Width = 90 };
        var cancel = new Button { Text = "Cancel", DialogResult = DialogResult.Cancel, AutoSize = true, Width = 90 };
        ok.Click += OnOk;

        var buttons = new FlowLayoutPanel
        {
            FlowDirection = FlowDirection.RightToLeft,
            Dock = DockStyle.Top,
            AutoSize = true,
            Padding = new Padding(0, 10, 0, 0),
        };
        buttons.Controls.Add(cancel);
        buttons.Controls.Add(ok);

        var root = new TableLayoutPanel
        {
            ColumnCount = 1,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            Dock = DockStyle.Fill,
        };
        root.Controls.Add(_fields, 0, 0);
        root.Controls.Add(buttons, 0, 1);
        Controls.Add(root);

        AcceptButton = ok;
        CancelButton = cancel;
    }

    /// <summary>Shows the editor for a copy of <paramref name="step"/>; returns the edited copy or null.</summary>
    public static RuleStep? Edit(IWin32Window owner, RuleStep step, string title)
    {
        using var dialog = new StepDialog(step.Clone(), title);
        return dialog.ShowDialog(owner) == DialogResult.OK ? dialog._working : null;
    }

    public static RuleStep? CreateNew(IWin32Window owner, string op)
    {
        RuleStep fresh = op switch
        {
            "replace" => new ReplaceStep(),
            "insert" => new InsertStep(),
            "remove" => new RemoveStep { From = 0, Count = 1 },
            "sequence" => new SequenceStep(),
            "case" => new CaseStep(),
            "extension" => new ExtensionStep(),
            _ => throw new ArgumentOutOfRangeException(nameof(op)),
        };

        return Edit(owner, fresh, "Add step — " + op);
    }

    private void BuildFields()
    {
        switch (_working)
        {
            case ReplaceStep s:
                _find = AddTextRow("Find", s.Find);
                _replaceWith = AddTextRow("Replace with", s.ReplaceWith);
                _regex = AddCheckRow("Regular expression ($1 for groups)", s.Regex);
                _ignoreCase = AddCheckRow("Ignore case", s.IgnoreCase);
                break;

            case InsertStep s:
                _text = AddTextRow("Text", s.Text);
                _position = AddComboRow("Position", new[] { "prefix", "suffix", "index" }, s.Position.ToString().ToLowerInvariant());
                _index = AddNumberRow("Index", s.Index, 0, 100000);
                _position.SelectedIndexChanged += (_, _) => _index!.Enabled = _position!.SelectedIndex == 2;
                _index.Enabled = s.Position == InsertPosition.Index;
                break;

            case RemoveStep s:
                _from = AddNumberRow("From index", s.From, 0, 100000);
                _count = AddNumberRow("Count", s.Count, 0, 100000);
                break;

            case SequenceStep s:
                _pattern = AddTextRow("Pattern", s.Pattern);
                AddHint("Exactly one {n:000} token; the zeros set the padding width.");
                _start = AddNumberRow("Start", s.Start, -1000000, 1000000);
                _step = AddNumberRow("Step", s.Step, -100000, 100000);
                _position = AddComboRow("Position", new[] { "prefix", "suffix" }, s.Position.ToString().ToLowerInvariant());
                break;

            case CaseStep s:
                _mode = AddComboRow("Mode", new[] { "upper", "lower", "title" }, s.Mode.ToString().ToLowerInvariant());
                break;

            case ExtensionStep s:
                _mode = AddComboRow("Mode", new[] { "lower", "upper", "set" }, s.Mode.ToString().ToLowerInvariant());
                _value = AddTextRow("Value (no leading dot)", s.Value);
                _mode.SelectedIndexChanged += (_, _) => _value!.Enabled = _mode!.SelectedIndex == 2;
                _value.Enabled = s.Mode == ExtensionMode.Set;
                break;
        }
    }

    private void OnOk(object? sender, EventArgs e)
    {
        switch (_working)
        {
            case ReplaceStep s:
                s.Find = _find!.Text;
                s.ReplaceWith = _replaceWith!.Text;
                s.Regex = _regex!.Checked;
                s.IgnoreCase = _ignoreCase!.Checked;
                if (s.Regex && !IsValidRegex(s.Find, out var regexError))
                {
                    MessageBox.Show(this, "That regular expression does not compile:\n\n" + regexError,
                        "Invalid pattern", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    DialogResult = DialogResult.None;
                }

                break;

            case InsertStep s:
                s.Text = _text!.Text;
                s.Position = (InsertPosition)_position!.SelectedIndex;
                s.Index = (int)_index!.Value;
                break;

            case RemoveStep s:
                s.From = (int)_from!.Value;
                s.Count = (int)_count!.Value;
                break;

            case SequenceStep s:
                s.Pattern = _pattern!.Text;
                s.Start = (int)_start!.Value;
                s.Step = (int)_step!.Value;
                s.Position = (SequencePosition)_position!.SelectedIndex;
                break;

            case CaseStep s:
                s.Mode = (CaseMode)_mode!.SelectedIndex;
                break;

            case ExtensionStep s:
                s.Mode = (ExtensionMode)_mode!.SelectedIndex;
                s.Value = _value!.Text;
                break;
        }
    }

    private static bool IsValidRegex(string pattern, out string error)
    {
        try
        {
            _ = new Regex(pattern);
            error = string.Empty;
            return true;
        }
        catch (ArgumentException ex)
        {
            error = ex.Message;
            return false;
        }
    }

    private TextBox AddTextRow(string label, string value)
    {
        var box = new TextBox { Text = value, Dock = DockStyle.Fill };
        AddRow(label, box);
        return box;
    }

    private CheckBox AddCheckRow(string label, bool value)
    {
        var box = new CheckBox { Text = label, Checked = value, AutoSize = true, Dock = DockStyle.Fill };
        AddRow(string.Empty, box);
        return box;
    }

    private ComboBox AddComboRow(string label, string[] options, string selected)
    {
        var combo = new ComboBox { DropDownStyle = ComboBoxStyle.DropDownList, Dock = DockStyle.Fill };
        combo.Items.AddRange(options);
        combo.SelectedIndex = Math.Max(0, Array.IndexOf(options, selected));
        AddRow(label, combo);
        return combo;
    }

    private NumericUpDown AddNumberRow(string label, int value, int min, int max)
    {
        var spin = new NumericUpDown
        {
            Minimum = min,
            Maximum = max,
            Value = Math.Clamp(value, min, max),
            Dock = DockStyle.Fill,
        };
        AddRow(label, spin);
        return spin;
    }

    private void AddHint(string text)
    {
        var hint = new Label
        {
            Text = text,
            AutoSize = true,
            ForeColor = SystemColors.GrayText,
            Margin = new Padding(3, 0, 3, 6),
        };
        AddRow(string.Empty, hint);
    }

    private void AddRow(string label, Control control)
    {
        var row = _fields.RowCount;
        _fields.RowCount = row + 1;
        _fields.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        _fields.Controls.Add(
            new Label
            {
                Text = label.Length > 0 ? label + ":" : string.Empty,
                AutoSize = true,
                Anchor = AnchorStyles.Left,
                Margin = new Padding(3, 7, 8, 3),
            },
            0,
            row);
        _fields.Controls.Add(control, 1, row);
    }
}

