using System.ComponentModel;
using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>Row shown in the preview grid.</summary>
internal sealed class PreviewRow
{
    public string Original { get; init; } = string.Empty;

    public string Proposed { get; init; } = string.Empty;

    public string Status { get; init; } = string.Empty;

    public string Reason { get; init; } = string.Empty;
}

internal sealed class MainForm : Form
{
    private static readonly Color OkBack = Color.FromArgb(232, 245, 233);
    private static readonly Color CollisionBack = Color.FromArgb(255, 231, 231);
    private static readonly Color InvalidBack = Color.FromArgb(255, 243, 214);
    private static readonly Color UnchangedBack = Color.FromArgb(245, 245, 245);

    private readonly RuleSet _rules = new();
    private readonly UndoManager _undo = new();
    private readonly BindingList<PreviewRow> _rows = new();

    private List<FileEntry> _files = new();
    private RenamePlan? _plan;
    private string _folder = string.Empty;
    private bool _suspendPreview;

    private readonly TextBox _folderBox = new() { ReadOnly = true, Dock = DockStyle.Fill };
    private readonly ComboBox _applyToBox = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 190 };
    private readonly ComboBox _sortBox = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 150 };
    private readonly ListBox _rulesList = new() { Dock = DockStyle.Fill, IntegralHeight = false };
    private readonly DataGridView _grid = new();
    private readonly Label _summaryLabel = new() { AutoSize = true, Padding = new Padding(4, 8, 4, 4) };
    private readonly Button _applyButton = new() { Text = "Apply rename", AutoSize = true, Height = 30 };
    private readonly Button _undoButton = new() { Text = "Undo last batch", AutoSize = true, Height = 30 };
    private readonly Button _exportButton = new() { Text = "Export plan.json…", AutoSize = true, Height = 30 };
    private readonly Button _editButton = new() { Text = "Edit", Width = 74 };
    private readonly Button _removeButton = new() { Text = "Remove", Width = 74 };
    private readonly Button _upButton = new() { Text = "Up", Width = 54 };
    private readonly Button _downButton = new() { Text = "Down", Width = 54 };

    public MainForm()
    {
        Text = "Batch Rename Studio";
        MinimumSize = new Size(940, 560);
        Size = new Size(1140, 700);
        StartPosition = FormStartPosition.CenterScreen;
        AutoScaleMode = AutoScaleMode.Dpi;
        AllowDrop = true;

        BuildLayout();
        WireEvents();

        _applyToBox.SelectedIndex = 0;
        _sortBox.SelectedIndex = 0;
        RefreshRulesList();
        UpdateEnabledState();
    }

    // ---------------------------------------------------------------- layout

    private void BuildLayout()
    {
        var menu = BuildMenu();
        MainMenuStrip = menu;

        var root = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 3,
            Padding = new Padding(10, 6, 10, 8),
        };
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        root.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));

        root.Controls.Add(BuildHeader(), 0, 0);
        root.Controls.Add(BuildSplit(), 0, 1);
        root.Controls.Add(BuildFooter(), 0, 2);

        Controls.Add(root);
        Controls.Add(menu);
    }

    private MenuStrip BuildMenu()
    {
        var menu = new MenuStrip { Dock = DockStyle.Top };

        var file = new ToolStripMenuItem("&File");
        file.DropDownItems.Add("&Open folder…", null, (_, _) => BrowseForFolder());
        file.DropDownItems.Add("&Rescan folder", null, (_, _) => Rescan());
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add("&Load rules…", null, (_, _) => LoadRules());
        file.DropDownItems.Add("&Save rules as…", null, (_, _) => SaveRules());
        file.DropDownItems.Add("&Export plan.json…", null, (_, _) => ExportPlan());
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add("E&xit", null, (_, _) => Close());

        var rules = new ToolStripMenuItem("&Rules");
        var add = new ToolStripMenuItem("&Add step");
        foreach (var op in new[] { "replace", "insert", "remove", "sequence", "case", "extension" })
        {
            var captured = op;
            add.DropDownItems.Add(op, null, (_, _) => AddStep(captured));
        }

        rules.DropDownItems.Add(add);
        rules.DropDownItems.Add("&Edit selected", null, (_, _) => EditSelectedStep());
        rules.DropDownItems.Add("&Remove selected", null, (_, _) => RemoveSelectedStep());
        rules.DropDownItems.Add(new ToolStripSeparator());
        rules.DropDownItems.Add("Remove &all steps", null, (_, _) => ClearSteps());

        var actions = new ToolStripMenuItem("&Actions");
        actions.DropDownItems.Add("&Apply rename", null, (_, _) => ApplyRename());
        actions.DropDownItems.Add("&Undo last batch", null, (_, _) => UndoLast());

        var help = new ToolStripMenuItem("&Help");
        help.DropDownItems.Add("&Headless mode…", null, (_, _) => ShowHeadlessHelp());
        help.DropDownItems.Add("&About", null, (_, _) => ShowAbout());

        menu.Items.AddRange(new ToolStripItem[] { file, rules, actions, help });
        return menu;
    }

    private Control BuildHeader()
    {
        var header = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 4,
            RowCount = 2,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
        };
        header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        header.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));

        header.Controls.Add(
            new Label { Text = "Folder:", AutoSize = true, Anchor = AnchorStyles.Left, Margin = new Padding(3, 7, 6, 3) },
            0,
            0);
        header.Controls.Add(_folderBox, 1, 0);

        var browse = new Button { Text = "Browse…", Width = 92 };
        browse.Click += (_, _) => BrowseForFolder();
        header.Controls.Add(browse, 2, 0);

        var rescan = new Button { Text = "Rescan", Width = 78 };
        rescan.Click += (_, _) => Rescan();
        header.Controls.Add(rescan, 3, 0);

        _applyToBox.Items.AddRange(new object[] { "name (keep extension)", "name + extension" });
        _sortBox.Items.AddRange(new object[] { "name", "created", "modified" });

        var options = new FlowLayoutPanel { AutoSize = true, Dock = DockStyle.Fill, Margin = new Padding(0, 4, 0, 2) };
        options.Controls.Add(new Label { Text = "Steps apply to:", AutoSize = true, Margin = new Padding(3, 7, 4, 3) });
        options.Controls.Add(_applyToBox);
        options.Controls.Add(new Label { Text = "Processing order:", AutoSize = true, Margin = new Padding(18, 7, 4, 3) });
        options.Controls.Add(_sortBox);
        header.Controls.Add(options, 0, 1);
        header.SetColumnSpan(options, 4);

        return header;
    }

    private Control BuildSplit()
    {
        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            SplitterDistance = 400,
            FixedPanel = FixedPanel.Panel1,
        };

        // Left: the rule pipeline.
        var left = new TableLayoutPanel { Dock = DockStyle.Fill, ColumnCount = 1, RowCount = 3 };
        left.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        left.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        left.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        left.Controls.Add(
            new Label
            {
                Text = "Rules — applied top to bottom",
                AutoSize = true,
                Font = new Font(Font, FontStyle.Bold),
                Margin = new Padding(3, 3, 3, 5),
            },
            0,
            0);
        left.Controls.Add(_rulesList, 0, 1);

        var addButton = new Button { Text = "Add step ▾", Width = 92 };
        var addMenu = new ContextMenuStrip();
        foreach (var op in new[] { "replace", "insert", "remove", "sequence", "case", "extension" })
        {
            var captured = op;
            addMenu.Items.Add(op, null, (_, _) => AddStep(captured));
        }

        addButton.Click += (_, _) => addMenu.Show(addButton, new Point(0, addButton.Height));

        var buttons = new FlowLayoutPanel { AutoSize = true, Dock = DockStyle.Fill, Margin = new Padding(0, 6, 0, 0) };
        buttons.Controls.AddRange(new Control[] { addButton, _editButton, _removeButton, _upButton, _downButton });
        left.Controls.Add(buttons, 0, 2);
        split.Panel1.Controls.Add(left);

        // Right: the preview.
        _grid.Dock = DockStyle.Fill;
        _grid.AllowUserToAddRows = false;
        _grid.AllowUserToDeleteRows = false;
        _grid.AllowUserToResizeRows = false;
        _grid.ReadOnly = true;
        _grid.RowHeadersVisible = false;
        _grid.AutoGenerateColumns = false;
        _grid.SelectionMode = DataGridViewSelectionMode.FullRowSelect;
        _grid.MultiSelect = false;
        _grid.BorderStyle = BorderStyle.FixedSingle;
        _grid.EnableHeadersVisualStyles = false;
        _grid.ColumnHeadersDefaultCellStyle.Font = new Font(Font, FontStyle.Bold);
        _grid.Columns.AddRange(
            NewColumn("Original", nameof(PreviewRow.Original), 30),
            NewColumn("Proposed", nameof(PreviewRow.Proposed), 30),
            NewColumn("Status", nameof(PreviewRow.Status), 12),
            NewColumn("Reason", nameof(PreviewRow.Reason), 28));
        _grid.DataSource = _rows;

        var right = new TableLayoutPanel { Dock = DockStyle.Fill, ColumnCount = 1, RowCount = 2 };
        right.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        right.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        right.Controls.Add(
            new Label
            {
                Text = "Preview — identical to what --plan writes",
                AutoSize = true,
                Font = new Font(Font, FontStyle.Bold),
                Margin = new Padding(3, 3, 3, 5),
            },
            0,
            0);
        right.Controls.Add(_grid, 0, 1);
        split.Panel2.Controls.Add(right);

        return split;
    }

    private static DataGridViewTextBoxColumn NewColumn(string header, string property, float weight) => new()
    {
        HeaderText = header,
        DataPropertyName = property,
        AutoSizeMode = DataGridViewAutoSizeColumnMode.Fill,
        FillWeight = weight,
        SortMode = DataGridViewColumnSortMode.NotSortable,
    };

    private Control BuildFooter()
    {
        var footer = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 2,
            RowCount = 1,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            Margin = new Padding(0, 8, 0, 0),
        };
        footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        footer.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));

        footer.Controls.Add(_summaryLabel, 0, 0);

        var buttons = new FlowLayoutPanel
        {
            FlowDirection = FlowDirection.RightToLeft,
            AutoSize = true,
            Dock = DockStyle.Fill,
        };
        buttons.Controls.AddRange(new Control[] { _applyButton, _undoButton, _exportButton });
        footer.Controls.Add(buttons, 1, 0);

        return footer;
    }

    // ---------------------------------------------------------------- events

    private void WireEvents()
    {
        _applyToBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = _applyToBox.SelectedIndex == 1 ? ApplyToMode.NameAndExtension : ApplyToMode.Name;
            RefreshPreview();
        };

        _sortBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = (SortMode)Math.Max(0, _sortBox.SelectedIndex);
            RefreshPreview();
        };

        _rulesList.SelectedIndexChanged += (_, _) => UpdateEnabledState();
        _rulesList.DoubleClick += (_, _) => EditSelectedStep();
        _editButton.Click += (_, _) => EditSelectedStep();
        _removeButton.Click += (_, _) => RemoveSelectedStep();
        _upButton.Click += (_, _) => MoveSelectedStep(-1);
        _downButton.Click += (_, _) => MoveSelectedStep(1);

        _applyButton.Click += (_, _) => ApplyRename();
        _undoButton.Click += (_, _) => UndoLast();
        _exportButton.Click += (_, _) => ExportPlan();

        _grid.CellFormatting += OnGridCellFormatting;

        DragEnter += (_, e) =>
        {
            if (e.Data?.GetDataPresent(DataFormats.FileDrop) == true)
            {
                e.Effect = DragDropEffects.Copy;
            }
        };
        DragDrop += OnDragDrop;
    }

    private void OnDragDrop(object? sender, DragEventArgs e)
    {
        if (e.Data?.GetData(DataFormats.FileDrop) is not string[] paths || paths.Length == 0)
        {
            return;
        }

        var first = paths[0];
        var folder = Directory.Exists(first) ? first : Path.GetDirectoryName(first);
        if (!string.IsNullOrEmpty(folder))
        {
            SetFolder(folder);
        }
    }

    private void OnGridCellFormatting(object? sender, DataGridViewCellFormattingEventArgs e)
    {
        if (e.RowIndex < 0 || e.RowIndex >= _rows.Count)
        {
            return;
        }

        var row = _rows[e.RowIndex];
        e.CellStyle!.BackColor = row.Status switch
        {
            PlanStatus.Ok => OkBack,
            PlanStatus.Collision => CollisionBack,
            PlanStatus.Invalid => InvalidBack,
            _ => UnchangedBack,
        };

        if (row.Status == PlanStatus.Unchanged)
        {
            e.CellStyle.ForeColor = SystemColors.GrayText;
        }
    }

    // ---------------------------------------------------------------- folder

    private void BrowseForFolder()
    {
        using var dialog = new FolderBrowserDialog
        {
            Description = "Choose the folder whose files should be renamed",
            UseDescriptionForTitle = true,
            ShowNewFolderButton = false,
        };

        if (_folder.Length > 0 && Directory.Exists(_folder))
        {
            dialog.SelectedPath = _folder;
        }

        if (dialog.ShowDialog(this) == DialogResult.OK)
        {
            SetFolder(dialog.SelectedPath);
        }
    }

    private void SetFolder(string folder)
    {
        _folder = folder;
        _folderBox.Text = folder;
        Rescan();
    }

    private void Rescan()
    {
        if (_folder.Length == 0)
        {
            _files = new List<FileEntry>();
            RefreshPreview();
            return;
        }

        try
        {
            _files = FolderScanner.Scan(_folder);
        }
        catch (Exception ex)
        {
            _files = new List<FileEntry>();
            MessageBox.Show(this, ex.Message, "Cannot read folder", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }

        RefreshPreview();
    }

    // ---------------------------------------------------------------- rules

    private void AddStep(string op)
    {
        var step = StepDialog.CreateNew(this, op);
        if (step is null)
        {
            return;
        }

        _rules.Steps.Add(step);
        RefreshRulesList();
        _rulesList.SelectedIndex = _rules.Steps.Count - 1;
        RefreshPreview();
    }

    private void EditSelectedStep()
    {
        var index = _rulesList.SelectedIndex;
        if (index < 0 || index >= _rules.Steps.Count)
        {
            return;
        }

        var edited = StepDialog.Edit(this, _rules.Steps[index], "Edit step — " + _rules.Steps[index].Op);
        if (edited is null)
        {
            return;
        }

        _rules.Steps[index] = edited;
        RefreshRulesList();
        _rulesList.SelectedIndex = index;
        RefreshPreview();
    }

    private void RemoveSelectedStep()
    {
        var index = _rulesList.SelectedIndex;
        if (index < 0 || index >= _rules.Steps.Count)
        {
            return;
        }

        _rules.Steps.RemoveAt(index);
        RefreshRulesList();
        if (_rules.Steps.Count > 0)
        {
            _rulesList.SelectedIndex = Math.Min(index, _rules.Steps.Count - 1);
        }

        RefreshPreview();
    }

    private void MoveSelectedStep(int delta)
    {
        var index = _rulesList.SelectedIndex;
        var target = index + delta;
        if (index < 0 || target < 0 || target >= _rules.Steps.Count)
        {
            return;
        }

        (_rules.Steps[index], _rules.Steps[target]) = (_rules.Steps[target], _rules.Steps[index]);
        RefreshRulesList();
        _rulesList.SelectedIndex = target;
        RefreshPreview();
    }

    private void ClearSteps()
    {
        if (_rules.Steps.Count == 0)
        {
            return;
        }

        _rules.Steps.Clear();
        RefreshRulesList();
        RefreshPreview();
    }

    private void RefreshRulesList()
    {
        var selected = _rulesList.SelectedIndex;
        _rulesList.BeginUpdate();
        _rulesList.Items.Clear();
        for (var i = 0; i < _rules.Steps.Count; i++)
        {
            _rulesList.Items.Add($"{i + 1}.  {_rules.Steps[i].Describe()}");
        }

        _rulesList.EndUpdate();
        if (selected >= 0 && selected < _rulesList.Items.Count)
        {
            _rulesList.SelectedIndex = selected;
        }

        UpdateEnabledState();
    }

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Load rules",
            Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*",
        };

        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            var loaded = RuleSetJson.Load(dialog.FileName);
            _suspendPreview = true;
            _rules.Steps.Clear();
            foreach (var step in loaded.Steps)
            {
                _rules.Steps.Add(step);
            }

            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _applyToBox.SelectedIndex = loaded.ApplyTo == ApplyToMode.NameAndExtension ? 1 : 0;
            _sortBox.SelectedIndex = (int)loaded.Sort;
            _suspendPreview = false;

            RefreshRulesList();
            RefreshPreview();
        }
        catch (RuleSetFormatException ex)
        {
            _suspendPreview = false;
            MessageBox.Show(this, ex.Message, "Cannot load rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog
        {
            Title = "Save rules",
            Filter = "Rule sets (*.json)|*.json",
            FileName = "rules.json",
        };

        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            RuleSetJson.Save(dialog.FileName, _rules);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Cannot save rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void ExportPlan()
    {
        if (_plan is null)
        {
            return;
        }

        using var dialog = new SaveFileDialog
        {
            Title = "Export plan",
            Filter = "Plans (*.json)|*.json",
            FileName = "plan.json",
        };

        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            PlanJson.Save(dialog.FileName, _plan);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Cannot export plan", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    // ---------------------------------------------------------------- preview

    private void RefreshPreview()
    {
        if (_suspendPreview)
        {
            return;
        }

        try
        {
            _plan = PlanBuilder.Build(_files, _rules);
        }
        catch (Exception ex)
        {
            _plan = null;
            _summaryLabel.Text = "Rule error: " + ex.Message;
            _rows.Clear();
            UpdateEnabledState();
            return;
        }

        _grid.SuspendLayout();
        _rows.RaiseListChangedEvents = false;
        _rows.Clear();
        foreach (var item in _plan.Items)
        {
            _rows.Add(new PreviewRow
            {
                Original = item.Original,
                Proposed = item.Proposed,
                Status = item.Status,
                Reason = item.Reason,
            });
        }

        _rows.RaiseListChangedEvents = true;
        _rows.ResetBindings();
        _grid.ResumeLayout();

        var s = _plan.Summary;
        _summaryLabel.Text = string.Create(
            CultureInfo.InvariantCulture,
            $"{s.Total} file(s)   ·   ok {s.Ok}   ·   collision {s.Collision}   ·   unchanged {s.Unchanged}   ·   invalid {s.Invalid}");

        UpdateEnabledState();
    }

    private void UpdateEnabledState()
    {
        var hasSelection = _rulesList.SelectedIndex >= 0;
        _editButton.Enabled = hasSelection;
        _removeButton.Enabled = hasSelection;
        _upButton.Enabled = hasSelection && _rulesList.SelectedIndex > 0;
        _downButton.Enabled = hasSelection && _rulesList.SelectedIndex < _rules.Steps.Count - 1;

        _applyButton.Enabled = _folder.Length > 0 && (_plan?.Summary.Ok ?? 0) > 0;
        _exportButton.Enabled = _plan is not null;
        _undoButton.Enabled = _undo.CanUndo;
        _undoButton.Text = _undo.CanUndo
            ? $"Undo last batch ({_undo.Newest!.Operations.Count})"
            : "Undo last batch";
    }

    // ---------------------------------------------------------------- actions

    private void ApplyRename()
    {
        if (_folder.Length == 0)
        {
            return;
        }

        // Re-scan and re-plan right before touching the disk: the folder may have moved on since
        // the preview was drawn.
        Rescan();
        if (_plan is null || _plan.Summary.Ok == 0)
        {
            MessageBox.Show(this, "There is nothing to rename.", "Apply", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        var s = _plan.Summary;
        var message =
            $"Rename {s.Ok} file(s) in\n{_folder}\n\n" +
            $"Skipped: {s.Collision} collision, {s.Invalid} invalid, {s.Unchanged} unchanged.\n\n" +
            "This can be undone with “Undo last batch”.";

        if (MessageBox.Show(this, message, "Apply rename", MessageBoxButtons.OKCancel, MessageBoxIcon.Question)
            != DialogResult.OK)
        {
            return;
        }

        RenameOutcome outcome;
        using (new WaitCursorScope(this))
        {
            outcome = RenameExecutor.Apply(_folder, _plan);
            _undo.Record(_folder, outcome.Applied, DateTime.UtcNow);
        }

        Rescan();

        if (outcome.FailedCount > 0)
        {
            var detail = string.Join(
                Environment.NewLine,
                outcome.Failures.Take(12).Select(f => $"{f.From} → {f.To}: {f.Error}"));
            MessageBox.Show(
                this,
                $"Renamed {outcome.SucceededCount} file(s); {outcome.FailedCount} failed.\n\n{detail}",
                "Apply finished with errors",
                MessageBoxButtons.OK,
                MessageBoxIcon.Warning);
        }
        else
        {
            _summaryLabel.Text = $"Renamed {outcome.SucceededCount} file(s).   " + _summaryLabel.Text;
        }
    }

    private void UndoLast()
    {
        var batch = _undo.Newest;
        if (batch is null)
        {
            return;
        }

        var message = $"Undo this batch?\n\n{batch.Describe()}";
        if (MessageBox.Show(this, message, "Undo", MessageBoxButtons.OKCancel, MessageBoxIcon.Question)
            != DialogResult.OK)
        {
            return;
        }

        (RenameBatch Batch, RenameOutcome Outcome)? result;
        using (new WaitCursorScope(this))
        {
            result = _undo.UndoNewest();
        }

        if (result is null)
        {
            return;
        }

        if (string.Equals(result.Value.Batch.Folder, _folder, StringComparison.OrdinalIgnoreCase))
        {
            Rescan();
        }
        else
        {
            UpdateEnabledState();
        }

        var outcome = result.Value.Outcome;
        if (outcome.FailedCount > 0)
        {
            MessageBox.Show(
                this,
                $"Restored {outcome.SucceededCount} file(s); {outcome.FailedCount} could not be restored "
                + "(they may have been moved or renamed again outside this tool).",
                "Undo finished with errors",
                MessageBoxButtons.OK,
                MessageBoxIcon.Warning);
        }
    }

    private void ShowHeadlessHelp()
    {
        MessageBox.Show(
            this,
            "The same engine runs without a window:\n\n"
            + "BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>\n\n"
            + "It writes the plan as UTF-8 (no BOM), prints one summary line, renames nothing, "
            + "and exits with code 0 on success.\n\n"
            + "Use File ▸ Save rules as… to produce a rules.json matching what you see here.",
            "Headless mode",
            MessageBoxButtons.OK,
            MessageBoxIcon.Information);
    }

    private void ShowAbout()
    {
        MessageBox.Show(
            this,
            "Batch Rename Studio 1.0\n\nA preview-first batch renamer for Windows.\n"
            + "Every rename is journalled so a whole batch can be undone.",
            "About",
            MessageBoxButtons.OK,
            MessageBoxIcon.Information);
    }

    private sealed class WaitCursorScope : IDisposable
    {
        private readonly Form _form;
        private readonly Cursor _previous;

        public WaitCursorScope(Form form)
        {
            _form = form;
            _previous = form.Cursor;
            form.Cursor = Cursors.WaitCursor;
        }

        public void Dispose() => _form.Cursor = _previous;
    }
}

