namespace BatchRenameStudio.Core;

/// <summary>Which part of the file name the steps operate on.</summary>
public enum ApplyToMode
{
    /// <summary>Steps operate on the base name only; the extension is kept aside.</summary>
    Name,

    /// <summary>Steps operate on the whole file name, extension included.</summary>
    NameAndExtension,
}

/// <summary>Processing order of the files in the folder.</summary>
public enum SortMode
{
    Name,
    Created,
    Modified,
}

public enum InsertPosition
{
    Prefix,
    Suffix,
    Index,
}

public enum SequencePosition
{
    Prefix,
    Suffix,
}

public enum CaseMode
{
    Upper,
    Lower,
    Title,
}

public enum ExtensionMode
{
    Lower,
    Upper,
    Set,
}

/// <summary>One transformation in the rule pipeline.</summary>
public abstract class RuleStep
{
    /// <summary>The discriminator written to / read from <c>rules.json</c>.</summary>
    public abstract string Op { get; }

    public abstract RuleStep Clone();

    /// <summary>Single-line human readable summary shown in the rule list.</summary>
    public abstract string Describe();

    public override string ToString() => Describe();
}

public sealed class ReplaceStep : RuleStep
{
    public string Find { get; set; } = string.Empty;
    public string ReplaceWith { get; set; } = string.Empty;
    public bool Regex { get; set; }
    public bool IgnoreCase { get; set; }

    public override string Op => "replace";

    public override RuleStep Clone() => new ReplaceStep
    {
        Find = Find,
        ReplaceWith = ReplaceWith,
        Regex = Regex,
        IgnoreCase = IgnoreCase,
    };

    public override string Describe()
    {
        var flags = (Regex ? " [regex]" : string.Empty) + (IgnoreCase ? " [ignore case]" : string.Empty);
        return $"Replace  “{Find}” → “{ReplaceWith}”{flags}";
    }
}

public sealed class InsertStep : RuleStep
{
    public string Text { get; set; } = string.Empty;
    public InsertPosition Position { get; set; } = InsertPosition.Prefix;
    public int Index { get; set; }

    public override string Op => "insert";

    public override RuleStep Clone() => new InsertStep
    {
        Text = Text,
        Position = Position,
        Index = Index,
    };

    public override string Describe() => Position switch
    {
        InsertPosition.Prefix => $"Insert   “{Text}” at start",
        InsertPosition.Suffix => $"Insert   “{Text}” at end",
        _ => $"Insert   “{Text}” at index {Index}",
    };
}

public sealed class RemoveStep : RuleStep
{
    public int From { get; set; }
    public int Count { get; set; }

    public override string Op => "remove";

    public override RuleStep Clone() => new RemoveStep { From = From, Count = Count };

    public override string Describe() => $"Remove   {Count} char(s) from index {From}";
}

public sealed class SequenceStep : RuleStep
{
    public string Pattern { get; set; } = "{n:000}_";
    public int Start { get; set; } = 1;
    public int Step { get; set; } = 1;
    public SequencePosition Position { get; set; } = SequencePosition.Prefix;

    public override string Op => "sequence";

    public override RuleStep Clone() => new SequenceStep
    {
        Pattern = Pattern,
        Start = Start,
        Step = Step,
        Position = Position,
    };

    public override string Describe()
        => $"Sequence “{Pattern}” start {Start} step {Step} at {(Position == SequencePosition.Prefix ? "start" : "end")}";
}

public sealed class CaseStep : RuleStep
{
    public CaseMode Mode { get; set; } = CaseMode.Lower;

    public override string Op => "case";

    public override RuleStep Clone() => new CaseStep { Mode = Mode };

    public override string Describe() => $"Case     {Mode.ToString().ToLowerInvariant()}";
}

public sealed class ExtensionStep : RuleStep
{
    public ExtensionMode Mode { get; set; } = ExtensionMode.Lower;
    public string Value { get; set; } = string.Empty;

    public override string Op => "extension";

    public override RuleStep Clone() => new ExtensionStep { Mode = Mode, Value = Value };

    public override string Describe() => Mode == ExtensionMode.Set
        ? $"Ext      set to “{Value}”"
        : $"Ext      {Mode.ToString().ToLowerInvariant()}case";
}

/// <summary>A complete, ordered rule pipeline plus the file-level options.</summary>
public sealed class RuleSet
{
    public ApplyToMode ApplyTo { get; set; } = ApplyToMode.Name;

    public SortMode Sort { get; set; } = SortMode.Name;

    public List<RuleStep> Steps { get; } = new();

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var s in Steps)
        {
            copy.Steps.Add(s.Clone());
        }

        return copy;
    }
}

using System.Globalization;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>
/// The mutable state a step operates on.
/// <para>
/// Under <see cref="ApplyToMode.Name"/> the extension is held apart in <see cref="Ext"/> and the
/// steps see only the base name in <see cref="Text"/>. Under
/// <see cref="ApplyToMode.NameAndExtension"/>, <see cref="Text"/> IS the whole proposed name and
/// <see cref="Ext"/> is unused (contract rules 3 and 12).
/// </para>
/// </summary>
internal sealed class TargetState
{
    public string Text = string.Empty;

    public string Ext = string.Empty;

    public bool SeparateExt;

    public string Compose() => SeparateExt ? NameParts.Join(Text, Ext) : Text;
}

internal interface ICompiledStep
{
    /// <param name="index">0-based position of the file in processing order.</param>
    void Apply(TargetState state, int index);
}

/// <summary>Turns a declarative <see cref="RuleSet"/> into an executable pipeline.</summary>
internal static class StepCompiler
{
    /// <summary>
    /// A generous ceiling: a pathological user regex should degrade into "no change" rather than
    /// hang the GUI or the headless run.
    /// </summary>
    public static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(5);

    public static ICompiledStep[] Compile(RuleSet rules)
    {
        var compiled = new ICompiledStep[rules.Steps.Count];
        for (var i = 0; i < rules.Steps.Count; i++)
        {
            compiled[i] = CompileOne(rules.Steps[i]);
        }

        return compiled;
    }

    private static ICompiledStep CompileOne(RuleStep step) => step switch
    {
        ReplaceStep s => new CompiledReplace(s),
        InsertStep s => new CompiledInsert(s),
        RemoveStep s => new CompiledRemove(s),
        SequenceStep s => new CompiledSequence(s),
        CaseStep s => new CompiledCase(s),
        ExtensionStep s => new CompiledExtension(s),
        _ => throw new ArgumentOutOfRangeException(nameof(step), $"unsupported step type {step.GetType().Name}"),
    };

    private sealed class CompiledReplace : ICompiledStep
    {
        private readonly string _find;
        private readonly string _replaceWith;
        private readonly StringComparison _comparison;
        private readonly Regex? _regex;

        public CompiledReplace(ReplaceStep s)
        {
            _find = s.Find;
            _replaceWith = s.ReplaceWith;
            _comparison = s.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;

            if (s.Regex)
            {
                var options = RegexOptions.CultureInvariant;
                if (s.IgnoreCase)
                {
                    options |= RegexOptions.IgnoreCase;
                }

                // Throws for a malformed pattern; callers surface that as a rule-set error.
                _regex = new Regex(s.Find, options, RegexTimeout);
            }
        }

        public void Apply(TargetState state, int index)
        {
            if (_regex is not null)
            {
                try
                {
                    state.Text = _regex.Replace(state.Text, _replaceWith);
                }
                catch (RegexMatchTimeoutException)
                {
                    // Leave the name untouched rather than producing a half-applied result.
                }

                return;
            }

            if (_find.Length == 0)
            {
                return;
            }

            state.Text = state.Text.Replace(_find, _replaceWith, _comparison);
        }
    }

    private sealed class CompiledInsert : ICompiledStep
    {
        private readonly string _text;
        private readonly InsertPosition _position;
        private readonly int _index;

        public CompiledInsert(InsertStep s)
        {
            _text = s.Text;
            _position = s.Position;
            _index = s.Index;
        }

        public void Apply(TargetState state, int index)
        {
            switch (_position)
            {
                case InsertPosition.Prefix:
                    state.Text = _text + state.Text;
                    break;
                case InsertPosition.Suffix:
                    state.Text += _text;
                    break;
                default:
                    var at = Math.Clamp(_index, 0, state.Text.Length);
                    state.Text = state.Text.Insert(at, _text);
                    break;
            }
        }
    }

    private sealed class CompiledRemove : ICompiledStep
    {
        private readonly int _from;
        private readonly int _count;

        public CompiledRemove(RemoveStep s)
        {
            _from = s.From;
            _count = s.Count;
        }

        public void Apply(TargetState state, int index)
        {
            var length = state.Text.Length;
            var from = Math.Clamp(_from, 0, length);
            var count = Math.Clamp(_count, 0, length - from);
            if (count == 0)
            {
                return;
            }

            state.Text = state.Text.Remove(from, count);
        }
    }

    private sealed class CompiledSequence : ICompiledStep
    {
        private static readonly Regex TokenPattern =
            new(@"\{n:(0+)\}", RegexOptions.CultureInvariant | RegexOptions.Compiled);

        private readonly string _pattern;
        private readonly long _start;
        private readonly long _step;
        private readonly SequencePosition _position;

        public CompiledSequence(SequenceStep s)
        {
            _pattern = s.Pattern;
            _start = s.Start;
            _step = s.Step;
            _position = s.Position;
        }

        public void Apply(TargetState state, int index)
        {
            // Contract rule 9: the counter advances for EVERY file in processing order,
            // whatever that file's final status turns out to be.
            var value = _start + ((long)index * _step);
            var rendered = TokenPattern.Replace(
                _pattern,
                m => value.ToString(new string('0', m.Groups[1].Value.Length), CultureInfo.InvariantCulture));

            state.Text = _position == SequencePosition.Prefix
                ? rendered + state.Text
                : state.Text + rendered;
        }
    }

    private sealed class CompiledCase : ICompiledStep
    {
        private readonly CaseMode _mode;

        public CompiledCase(CaseStep s) => _mode = s.Mode;

        public void Apply(TargetState state, int index)
            => state.Text = CaseTransform.Apply(state.Text, _mode);
    }

    private sealed class CompiledExtension : ICompiledStep
    {
        private readonly ExtensionMode _mode;
        private readonly string _value;

        public CompiledExtension(ExtensionStep s)
        {
            _mode = s.Mode;
            _value = s.Value;
        }

        public void Apply(TargetState state, int index)
        {
            // Contract rule 11: always operates on the extension, regardless of applyTo.
            if (state.SeparateExt)
            {
                state.Ext = Transform(state.Ext);
                return;
            }

            // applyTo = nameAndExtension: act on the trailing extension of the current string.
            var (baseName, ext) = NameParts.Split(state.Text);
            state.Text = NameParts.Join(baseName, Transform(ext));
        }

        private string Transform(string ext) => _mode switch
        {
            ExtensionMode.Lower => ext.ToLowerInvariant(),
            ExtensionMode.Upper => ext.ToUpperInvariant(),
            _ => _value,
        };
    }
}

/// <summary>Contract rule 10.</summary>
public static class CaseTransform
{
    public static string Apply(string text, CaseMode mode) => mode switch
    {
        CaseMode.Upper => text.ToUpperInvariant(),
        CaseMode.Lower => text.ToLowerInvariant(),
        _ => ToTitle(text),
    };

    /// <summary>
    /// For each maximal run of Unicode letters: uppercase the first character, lowercase the rest.
    /// Every non-letter is left exactly as it was, and also breaks the run.
    /// </summary>
    public static string ToTitle(string text)
    {
        var chars = text.ToCharArray();
        var atRunStart = true;
        for (var i = 0; i < chars.Length; i++)
        {
            if (char.IsLetter(chars[i]))
            {
                chars[i] = atRunStart ? char.ToUpperInvariant(chars[i]) : char.ToLowerInvariant(chars[i]);
                atRunStart = false;
            }
            else
            {
                atRunStart = true;
            }
        }

        return new string(chars);
    }
}

using System.Text.RegularExpressions;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// One modal editor for all six step kinds. A single dialog that reshapes itself keeps the rule
/// editor's behaviour identical for "add" and "edit" and avoids six near-duplicate forms.
/// </summary>
internal sealed class StepDialog : Form
{
    private readonly RuleStep _working;
    private readonly TableLayoutPanel _fields;

    private TextBox? _find;
    private TextBox? _replaceWith;
    private CheckBox? _regex;
    private CheckBox? _ignoreCase;
    private TextBox? _text;
    private ComboBox? _position;
    private NumericUpDown? _index;
    private NumericUpDown? _from;
    private NumericUpDown? _count;
    private TextBox? _pattern;
    private NumericUpDown? _start;
    private NumericUpDown? _step;
    private ComboBox? _mode;
    private TextBox? _value;

    private StepDialog(RuleStep working, string title)
    {
        _working = working;

        Text = title;
        FormBorderStyle = FormBorderStyle.FixedDialog;
        MinimizeBox = false;
        MaximizeBox = false;
        ShowInTaskbar = false;
        StartPosition = FormStartPosition.CenterParent;
        AutoScaleMode = AutoScaleMode.Dpi;
        Padding = new Padding(12);
        AutoSize = true;
        AutoSizeMode = AutoSizeMode.GrowAndShrink;

        _fields = new TableLayoutPanel
        {
            ColumnCount = 2,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            Dock = DockStyle.Top,
        };
        _fields.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        _fields.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 320));

        BuildFields();

        var ok = new Button { Text = "OK", DialogResult = DialogResult.OK, AutoSize = true, Width = 90 };
        var cancel = new Button { Text = "Cancel", DialogResult = DialogResult.Cancel, AutoSize = true, Width = 90 };
        ok.Click += OnOk;

        var buttons = new FlowLayoutPanel
        {
            FlowDirection = FlowDirection.RightToLeft,
            Dock = DockStyle.Top,
            AutoSize = true,
            Padding = new Padding(0, 10, 0, 0),
        };
        buttons.Controls.Add(cancel);
        buttons.Controls.Add(ok);

        var root = new TableLayoutPanel
        {
            ColumnCount = 1,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            Dock = DockStyle.Fill,
        };
        root.Controls.Add(_fields, 0, 0);
        root.Controls.Add(buttons, 0, 1);
        Controls.Add(root);

        AcceptButton = ok;
        CancelButton = cancel;
    }

    /// <summary>Shows the editor for a copy of <paramref name="step"/>; returns the edited copy or null.</summary>
    public static RuleStep? Edit(IWin32Window owner, RuleStep step, string title)
    {
        using var dialog = new StepDialog(step.Clone(), title);
        return dialog.ShowDialog(owner) == DialogResult.OK ? dialog._working : null;
    }

    public static RuleStep? CreateNew(IWin32Window owner, string op)
    {
        RuleStep fresh = op switch
        {
            "replace" => new ReplaceStep(),
            "insert" => new InsertStep(),
            "remove" => new RemoveStep { From = 0, Count = 1 },
            "sequence" => new SequenceStep(),
            "case" => new CaseStep(),
            "extension" => new ExtensionStep(),
            _ => throw new ArgumentOutOfRangeException(nameof(op)),
        };

        return Edit(owner, fresh, "Add step — " + op);
    }

    private void BuildFields()
    {
        switch (_working)
        {
            case ReplaceStep s:
                _find = AddTextRow("Find", s.Find);
                _replaceWith = AddTextRow("Replace with", s.ReplaceWith);
                _regex = AddCheckRow("Regular expression ($1 for groups)", s.Regex);
                _ignoreCase = AddCheckRow("Ignore case", s.IgnoreCase);
                break;

            case InsertStep s:
                _text = AddTextRow("Text", s.Text);
                _position = AddComboRow("Position", new[] { "prefix", "suffix", "index" }, s.Position.ToString().ToLowerInvariant());
                _index = AddNumberRow("Index", s.Index, 0, 100000);
                _position.SelectedIndexChanged += (_, _) => _index!.Enabled = _position!.SelectedIndex == 2;
                _index.Enabled = s.Position == InsertPosition.Index;
                break;

            case RemoveStep s:
                _from = AddNumberRow("From index", s.From, 0, 100000);
                _count = AddNumberRow("Count", s.Count, 0, 100000);
                break;

            case SequenceStep s:
                _pattern = AddTextRow("Pattern", s.Pattern);
                AddHint("Exactly one {n:000} token; the zeros set the padding width.");
                _start = AddNumberRow("Start", s.Start, -1000000, 1000000);
                _step = AddNumberRow("Step", s.Step, -100000, 100000);
                _position = AddComboRow("Position", new[] { "prefix", "suffix" }, s.Position.ToString().ToLowerInvariant());
                break;

            case CaseStep s:
                _mode = AddComboRow("Mode", new[] { "upper", "lower", "title" }, s.Mode.ToString().ToLowerInvariant());
                break;

            case ExtensionStep s:
                _mode = AddComboRow("Mode", new[] { "lower", "upper", "set" }, s.Mode.ToString().ToLowerInvariant());
                _value = AddTextRow("Value (no leading dot)", s.Value);
                _mode.SelectedIndexChanged += (_, _) => _value!.Enabled = _mode!.SelectedIndex == 2;
                _value.Enabled = s.Mode == ExtensionMode.Set;
                break;
        }
    }

    private void OnOk(object? sender, EventArgs e)
    {
        switch (_working)
        {
            case ReplaceStep s:
                s.Find = _find!.Text;
                s.ReplaceWith = _replaceWith!.Text;
                s.Regex = _regex!.Checked;
                s.IgnoreCase = _ignoreCase!.Checked;
                if (s.Regex && !IsValidRegex(s.Find, out var regexError))
                {
                    MessageBox.Show(this, "That regular expression does not compile:\n\n" + regexError,
                        "Invalid pattern", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    DialogResult = DialogResult.None;
                }

                break;

            case InsertStep s:
                s.Text = _text!.Text;
                s.Position = (InsertPosition)_position!.SelectedIndex;
                s.Index = (int)_index!.Value;
                break;

            case RemoveStep s:
                s.From = (int)_from!.Value;
                s.Count = (int)_count!.Value;
                break;

            case SequenceStep s:
                s.Pattern = _pattern!.Text;
                s.Start = (int)_start!.Value;
                s.Step = (int)_step!.Value;
                s.Position = (SequencePosition)_position!.SelectedIndex;
                break;

            case CaseStep s:
                s.Mode = (CaseMode)_mode!.SelectedIndex;
                break;

            case ExtensionStep s:
                s.Mode = (ExtensionMode)_mode!.SelectedIndex;
                s.Value = _value!.Text;
                break;
        }
    }

    private static bool IsValidRegex(string pattern, out string error)
    {
        try
        {
            _ = new Regex(pattern);
            error = string.Empty;
            return true;
        }
        catch (ArgumentException ex)
        {
            error = ex.Message;
            return false;
        }
    }

    private TextBox AddTextRow(string label, string value)
    {
        var box = new TextBox { Text = value, Dock = DockStyle.Fill };
        AddRow(label, box);
        return box;
    }

    private CheckBox AddCheckRow(string label, bool value)
    {
        var box = new CheckBox { Text = label, Checked = value, AutoSize = true, Dock = DockStyle.Fill };
        AddRow(string.Empty, box);
        return box;
    }

    private ComboBox AddComboRow(string label, string[] options, string selected)
    {
        var combo = new ComboBox { DropDownStyle = ComboBoxStyle.DropDownList, Dock = DockStyle.Fill };
        combo.Items.AddRange(options);
        combo.SelectedIndex = Math.Max(0, Array.IndexOf(options, selected));
        AddRow(label, combo);
        return combo;
    }

    private NumericUpDown AddNumberRow(string label, int value, int min, int max)
    {
        var spin = new NumericUpDown
        {
            Minimum = min,
            Maximum = max,
            Value = Math.Clamp(value, min, max),
            Dock = DockStyle.Fill,
        };
        AddRow(label, spin);
        return spin;
    }

    private void AddHint(string text)
    {
        var hint = new Label
        {
            Text = text,
            AutoSize = true,
            ForeColor = SystemColors.GrayText,
            Margin = new Padding(3, 0, 3, 6),
        };
        AddRow(string.Empty, hint);
    }

    private void AddRow(string label, Control control)
    {
        var row = _fields.RowCount;
        _fields.RowCount = row + 1;
        _fields.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        _fields.Controls.Add(
            new Label
            {
                Text = label.Length > 0 ? label + ":" : string.Empty,
                AutoSize = true,
                Anchor = AnchorStyles.Left,
                Margin = new Padding(3, 7, 8, 3),
            },
            0,
            row);
        _fields.Controls.Add(control, 1, row);
    }
}

