/// <summary>
/// The executable is built for the console subsystem so that <c>--plan</c> behaves like a normal
/// command-line tool under every launcher (cmd, PowerShell, Python, MSBuild). When it is started
/// with no arguments — a double-click — the console it was given is not wanted, so it is released
/// before the window appears.
/// </summary>
internal static class ConsoleHost
{
    /// <summary>
    /// Detaches from the console, but only when this process is its sole owner. Started from an
    /// existing terminal, the console belongs to the shell and must be left alone.
    /// </summary>
    public static void ReleaseOwnConsole()
    {
        try
        {
            var owners = new uint[4];
            var count = GetConsoleProcessList(owners, (uint)owners.Length);
            if (count == 1)
            {
                FreeConsole();
            }
        }
        catch
        {
            // No console, or an API that is unavailable: nothing to release.
        }
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern uint GetConsoleProcessList(uint[] processList, uint processCount);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool FreeConsole();
}

