/// <summary>
/// Recognises the explicit GUI form. Returns false for everything else so the caller can fall
/// through to the headless commands.
/// </summary>
public static bool TryParseGui(string[] args, out string? folder, out string? rulesPath)
{
    folder = null;
    rulesPath = null;
    if (args.Length == 0 || args[0] != "--gui")
    {
        return false;
    }

    for (var i = 1; i < args.Length - 1; i++)
    {
        if (args[i] == "--dir")
        {
            folder = args[++i];
        }
        else if (args[i] == "--rules")
        {
            rulesPath = args[++i];
        }
    }

    return true;
}

