using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        // No arguments, or a single folder path (drag-and-drop onto the exe, "Open with"):
        // that is a request for the window, not for the command line.
        if (args.Length == 0 || (args.Length == 1 && !args[0].StartsWith('-') && Directory.Exists(args[0])))
        {
            ConsoleHost.ReleaseOwnConsole();
            RunGui(args.Length == 1 ? args[0] : null);
            return CommandLine.ExitSuccess;
        }

        try
        {
            return CommandLine.Run(args);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return CommandLine.ExitRuntimeError;
        }
    }

    private static void RunGui(string? initialFolder)
    {
        Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.Run(new MainForm(initialFolder));
    }
}

