private static void RunGui(string? initialFolder, string? initialRules)
{
    Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);
    Application.EnableVisualStyles();
    Application.SetCompatibleTextRenderingDefault(false);

    // A window that vanishes without a word is the worst possible failure mode; make every
    // unexpected error announce itself instead.
    Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
    Application.ThreadException += (_, e) => ReportCrash(e.Exception);
    AppDomain.CurrentDomain.UnhandledException += (_, e) => ReportCrash(e.ExceptionObject as Exception);

    try
    {
        Application.Run(new MainForm(initialFolder, initialRules));
    }
    catch (Exception ex)
    {
        ReportCrash(ex);
    }
}

private static void ReportCrash(Exception? ex)
{
    var text = ex?.ToString() ?? "Unknown error.";
    Console.Error.WriteLine(text);
    try
    {
        MessageBox.Show(
            text.Length > 2000 ? text[..2000] + "…" : text,
            "Batch Rename Studio — unexpected error",
            MessageBoxButtons.OK,
            MessageBoxIcon.Error);
    }
    catch
    {
        // Nothing left to do if even the dialog fails.
    }
}

