Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class C {
    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
    [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
    [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT r);
    [DllImport("user32.dll")] public static extern bool SetCursorPos(int x, int y);
    [DllImport("user32.dll")] public static extern void mouse_event(uint f, uint dx, uint dy, uint d, IntPtr e);
    [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
    public static void Click(int x, int y) {
        SetCursorPos(x, y);
        System.Threading.Thread.Sleep(150);
        mouse_event(0x0002, 0, 0, 0, IntPtr.Zero);
        mouse_event(0x0004, 0, 0, 0, IntPtr.Zero);
    }
}
"@

[void][C]::SetProcessDPIAware()
$p = Get-Process -Id $ProcessId
$main = New-Object C+RECT
[void][C]::GetWindowRect($p.MainWindowHandle, [ref]$main)
[void][C]::SetForegroundWindow($p.MainWindowHandle)
Start-Sleep -Milliseconds 600
"main at $($main.Left),$($main.Top)"

foreach ($pt in $Points.Split(';')) {
    $xy = $pt.Split(',')
    $x = $main.Left + [int]$xy[0]
    $y = $main.Top + [int]$xy[1]
    "click $x,$y"
    [C]::Click($x, $y)
    Start-Sleep -Milliseconds 700
}

Start-Sleep -Milliseconds 600
$h = [C]::GetForegroundWindow()
$r = New-Object C+RECT
[void][C]::GetWindowRect($h, [ref]$r)
$w = $r.Right - $r.Left
$ht = $r.Bottom - $r.Top
"foreground rect ${w}x${ht} at $($r.Left),$($r.Top)"
$bmp = New-Object System.Drawing.Bitmap($w, $ht)
$g = [System.Drawing.Graphics]::FromImage($bmp)
$g.CopyFromScreen($r.Left, $r.Top, 0, 0, (New-Object System.Drawing.Size($w, $ht)))
$g.Dispose()
$bmp.Save($Out, [System.Drawing.Imaging.ImageFormat]::Png)
$bmp.Dispose()
"saved $Out"

