[void][C]::SetWindowPos($p.MainWindowHandle, [IntPtr]::Zero, 40, 40, 0, 0, 0x0005)
Start-Sleep -Milliseconds 400
$main = New-Object C+RECT
[void][C]::GetWindowRect($p.MainWindowHandle, [ref]$main)
[void][C]::SetForegroundWindow($p.MainWindowHandle)
Start-Sleep -Milliseconds 600
"main at $($main.Left),$($main.Top)"

Add-Type -AssemblyName System.Windows.Forms

foreach ($pt in $Points.Split(';')) {
    if ($pt.StartsWith('K:')) {
        [System.Windows.Forms.SendKeys]::SendWait($pt.Substring(2))
        Start-Sleep -Milliseconds 700
        continue
    }
    $xy = $pt.Split(',')
    $x = $main.Left + [int]$xy[0]
    $y = $main.Top + [int]$xy[1]
    "click $x,$y"
    [C]::Click($x, $y)
    Start-Sleep -Milliseconds 700
}

Start-Sleep -Milliseconds 600
$h = [C]::GetForegroundWindow()
$r = New-Object C+RECT
[void][C]::GetWindowRect($h, [ref]$r)
$w = $r.Right - $r.Left
$ht = $r.Bottom - $r.Top
"foreground rect ${w}x${ht} at $($r.Left),$($r.Top)"
$bmp = New-Object System.Drawing.Bitmap($w, $ht)
$g = [System.Drawing.Graphics]::FromImage($bmp)
$g.CopyFromScreen($r.Left, $r.Top, 0, 0, (New-Object System.Drawing.Size($w, $ht)))
$g.Dispose()
$bmp.Save($Out, [System.Drawing.Imaging.ImageFormat]::Png)
$bmp.Dispose()
"saved $Out"

